const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const description = '<p><strong>Source document:</strong> <a href="' + esc($json.docUrl) + '" target="_blank" rel="noopener noreferrer">' + esc($json.docName) + '</a></p>' + '<p><strong>Cycle:</strong> ' + esc($json.cycle_id) + '</p>' + '<p><strong>Validation:</strong> use the approval links in the first task comment.</p>' + '<p>Rule: move to Done only when both stamps are APPROVED.</p>';
return { ...$json, createTaskInput: { project_id: Number($vars.WF02_PROJECT_ID || 117), title: $json.title, description, assignee: $json.author_username, coworkers: ['nadia', 'etienne'], status_id: Number($vars.WF02_INPROGRESS_STATUS_ID || 475), priority: 'NORMAL' } };
